import{Lt as e,Vt as t,Z as n,_t as r,bt as i,vt as a}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";var o=JSON.parse(`{"title":"移动端","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/mobile.md","filePath":"wiki/user-guide/mobile.md"}`),s={name:`user-guide/mobile.md`};function c(n,o,s,c,l,u){let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),r(`div`,null,[o[0]||=a(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /user-guidemobile.md for this page in Markdown format</div><h1 id="移动端" tabindex="-1">移动端 <a class="header-anchor" href="#移动端" aria-label="Permalink to “移动端”">​</a></h1><h2 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to “iOS”">​</a></h2><p>官方已经发布了 Zotero for iOS，并且支持支持 WebDAV 同步，iOS 端的设置相对比较简单，只需要登录 Zotero 账户和完成 WebDAV 网盘设置即可。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>见 <a href="./install#ios">安装</a>。</p><h3 id="配置同步" tabindex="-1">配置同步 <a class="header-anchor" href="#配置同步" aria-label="Permalink to “配置同步”">​</a></h3><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">提示</p><p>在进行该部分操作时，请确保您拥有「Zotero 账户」、「具有 WebDAV 同步功能的网盘」、「完成 PC 端相关设置」。</p></div><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">警告</p><p>要使用 iOS 客户端，需要使用官方同步或 WebDAV 同步二者之一，才能顺利同步附件。其他使用 ZotFile 等链接文件的同步方式不支持，未来也不会支持。</p></div><ol><li><p>在第一次打开 Zotero 时，会提醒登录，选择 Sign In（此时需要登录你的 Zotero 账户）</p><p><img src="/assets/iOS%E7%99%BB%E9%99%86.DWYgn2dW.jpg" alt="登录 Zotero 账户" width="50%"></p></li><li><p>登录完成后，返回 app 主页，点击右上角的齿轮图标</p><p><img src="/assets/iOS%E9%A6%96%E9%A1%B5.BNx49nYs.png" alt="app 首页" width="451" height="976"></p></li><li><p>点击 <code>account</code> 进入同步设置</p></li><li><p>从上到下依次为：</p><ul><li>附件同步方式：<code>WebDAV</code></li><li>WebDAV 地址：<code>dav.jianguoyun.com/dav</code></li><li>坚果云账户：邮箱</li><li>密码：此处的密码是在坚果云中创建的应用密码，不是坚果云网盘的登录密码）</li></ul><details class="details custom-block"><summary>如何获取坚果云的应用密码</summary><ol><li><p>在<a href="https://www.jianguoyun.com/d/login" target="_blank" rel="noreferrer">坚果云官网登录</a>您的坚果云账户。</p></li><li><p>登录后点击 右侧用户名-&gt;账户信息</p></li></ol><p><img src="data:image/png;base64," alt="账户信息" width="160" height="226"></p><ol start="3"><li>选择安全选项，下滑到底，点击添加应用。</li></ol><p><img src="/assets/%E5%9D%9A%E6%9E%9C%E4%BA%91-%E6%B7%BB%E5%8A%A0%E5%BA%94%E7%94%A8.CF4_T-X_.png" alt="添加应用" width="1710" height="673"></p><ol start="4"><li>完成后，记录下生成的密码。</li></ol><p><img src="data:image/png;base64," alt="生成应用密码" width="452" height="99"></p><p><img src="data:image/png;base64," alt="复制应用密码" width="437" height="93"></p></details><p>验证服务器后显示 <code>Verified</code> 表示设置成功。</p><p><img src="/assets/iOS%E5%90%8C%E6%AD%A5%E7%99%BB%E9%99%86.Ca-3HOAP.png" alt="iOS 同步登陆" width="500" height="1067"></p></li><li><p>等待片刻文献即可同步成功。可以点击文献直接阅读，也点击文献右侧的 <code>i</code> 标志查看文献信息 <img src="/assets/iOS%E6%96%87%E7%8C%AE%E5%90%8C%E6%AD%A5%E6%88%90%E5%8A%9F.BhDTBCW-.png" alt="文献同步成功" width="333" height="720"></p></li><li><p>在文献阅读时，可以进行高亮内容，任意划线等操作。完成阅读是直接返回，你的阅读记录会后台自动同步到其他客户端。 <img src="/assets/iOS%E6%96%87%E7%8C%AE%E9%98%85%E8%AF%BB.DYNyx8F9.png" alt="文献阅读" width="333" height="720"></p></li></ol><h2 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to “Android”">​</a></h2><p>Zotero 官方已于 2025 年 6 月 5 日<a href="https://www.zotero.org/blog/zotero-for-android/" target="_blank" rel="noreferrer">正式发布 Android 版本客户端</a>。</p><h3 id="安装-1" tabindex="-1">安装 <a class="header-anchor" href="#安装-1" aria-label="Permalink to “安装”">​</a></h3><p>见 <a href="./install#android">安装</a>。</p><h3 id="配置同步-1" tabindex="-1">配置同步 <a class="header-anchor" href="#配置同步-1" aria-label="Permalink to “配置同步”">​</a></h3><p>Zotero 官方 Android 客户端的配置方法与 iOS 端大体相同，请参考详见 <a href="#ios">iOS</a> 进行配置，此处不再赘述。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">警告</p><p>要使用 Android 客户端，需要使用官方同步或 WebDAV 同步二者之一，才能顺利同步附件。其他使用 ZotFile 等链接文件的同步方式不支持，未来也不会支持。</p></div>`,17),i(d),i(f)])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};